pub fn mul_m31(self, rhs: M31) -> CM31 {
        CM31 {
            a: self.a.mul(rhs),
            b: self.b.mul(rhs),
        }
    }

pub fn mul_m31(self, rhs: M31) -> QM31 {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::KMulF);
        QM31 {
            c0: self.c0.mul_m31(rhs),
            c1: self.c1.mul_m31(rhs),
        }
    }

pub fn build_pool_v1_pair_forest_copy_helper_v1(
    trace: &PoolV1PairForestTraceV1,
    append_index: u64,
    lambda: QM31,
    chi: QM31,
) -> Result<Vec<QM31>, PoolV1PairTraceErrorV1> {
    let rows = pool_v1_pair_forest_copy_rows_v1(trace, append_index, lambda)?;
    build_copy_logup_helper(&rows, chi).map_err(|_| PoolV1PairTraceErrorV1::CopyImbalance)
}

pub fn build_copy_logup_helper(rows: &[CopyLogUpRow], chi: QM31) -> Result<Vec<QM31>, LogUpError> {
    let mut helper = Vec::with_capacity(rows.len());
    for (row_index, row) in rows.iter().enumerate() {
        let mut value = QM31::ZERO;
        for (producer_value, weight) in row.producer_values.into_iter().zip(row.producer_weights) {
            if weight != M31::ZERO {
                value = value.add(
                    chi.sub(producer_value)
                        .try_inv()
                        .ok_or(LogUpError::ActivePole {
                            row: row_index,
                            side: LogUpSide::Producer,
                        })?
                        .mul_m31(weight),
                );
            }
        }
        for (consumer_value, weight) in row.consumer_values.into_iter().zip(row.consumer_weights) {
            if weight != M31::ZERO {
                value = value.sub(
                    chi.sub(consumer_value)
                        .try_inv()
                        .ok_or(LogUpError::ActivePole {
                            row: row_index,
                            side: LogUpSide::Consumer,
                        })?
                        .mul_m31(weight),
                );
            }
        }
        helper.push(value);
    }
    Ok(helper)
}

fn base_p_digits(mut rank: Rank) -> [u32; 8] {
    core::array::from_fn(|_| {
        let mut remainder = 0u64;
        for limb in rank.iter_mut().rev() {
            let dividend = (remainder << 32) | u64::from(*limb);
            *limb = (dividend / u64::from(P)) as u32;
            remainder = dividend % u64::from(P);
        }
        remainder as u32
    })
}

pub fn qm31_sample(block: &[u8; 32]) -> QM31 {
    let d = base_p_digits(reduce_rank(block_rank(block), P4));
    decode4([d[0], d[1], d[2], d[3]])
}

fn build_pair_forest_mode(
        public: Public<'_>,
        compiled: &PoolV1PairForestMergedC1CompilationV1,
        mask_only: &[Vec<M31>; 10],
        d: &[QM31; 1024],
        g: &[QM31; 1024],
        commitments: &mut impl Commitments,
        hash: HashFn,
        transported_endpoints: bool,
    ) -> Result<BuiltSemantics, Error> {
        if compiled.semantic_c1.c1.len() != 16 || &compiled.public_statement != public.transition()
        {
            return Err(Error::Public);
        }
        let c1 = core::array::from_fn(|i| {
            if i < 16 {
                compiled.semantic_c1.c1[i].clone()
            } else {
                mask_only[i - 16].clone()
            }
        });
        build_with_helper_mode(
            public,
            &c1,
            d,
            g,
            |lambda, chi| {
                build_pool_v1_pair_forest_copy_helper_v1(
                    &compiled.trace,
                    public.transition().live_snapshot.next_pair_index,
                    lambda,
                    chi,
                )
                .map_err(|_| Error::Public)
            },
            commitments,
            hash,
            transported_endpoints,
        )
    }
